insert into public.plans (code,name_en,name_th,series,style,storeys,area_sqm,floor_areas,bedrooms,bathrooms,parking,land_width,land_depth,min_land_sqwa,build_cost_min,build_cost_max,price,price_original,badge,tagline,description,image,gallery,features,pages_arch,pages_struct,pages_mep,sort_order) values
('AP-NORDIC-08','Nordic Panoramic Villa','แบบบ้านพูลวิลล่าสองชั้น','Nordic Modern Series','nordic',2,320,'[185,135]',4,4,2,16.5,20,82.5,4.8,5.5,32900,45000,'BEST SELLER','หลังคาจั่วองศาชัน หน้าต่างกระจกสูงสองชั้น รับวิวสวนและแสงธรรมชาติ','วิลล่านอร์ดิกสองชั้นหลังคาเมทัลชีท Standing Seam ไร้รอยต่อ ผนังไม้สังเคราะห์สีเข้มตัดกระจก Double Volume โถงนั่งเล่นเพดานสูงเชื่อมต่อเทอร์เรซไม้ ห้องนอนใหญ่ชั้นบนพร้อมระเบียงส่วนตัว ออกแบบให้ช่องลมถ่ายเทตามทิศลมประจำของภาคอีสาน','/images/nordic-villa.jpg','{/images/nordic-villa.jpg,/images/section-cutaway.jpg,/images/interior-360.jpg}','{tour360,dollhouse}',38,24,18,10),
('AP-TROPICAL-02','Tropical Oasis','บ้านโมเดิร์นทรอปิคอลพร้อมสระว่ายน้ำ','Modern Resort Living','tropical',2,385,'[205,180]',4,5,2,18,24,108,6.2,7.0,36000,48000,'TROPICAL LUXURY','บ้านพักตากอากาศสไตล์รีสอร์ต ชายคายื่นยาวกันแดดฝน พร้อมสระว่ายน้ำ','บ้านสองชั้นสไตล์รีสอร์ตโมเดิร์นทรอปิคอล ชายคายื่นลึกบังแดดบ่าย ระแนงไม้สังเคราะห์ช่วยกรองแสง สระว่ายน้ำระบบเกลือขนาด 4 x 10 เมตร ติดห้องนั่งเล่นแบบเปิดโล่ง ห้องนอนทุกห้องมีห้องน้ำในตัว','/images/tropical-villa.jpg','{/images/tropical-villa.jpg,/images/interior-360.jpg,/images/section-cutaway.jpg}','{tour360,pool}',42,26,20,20),
('AP-JAPANDI-01','Courtyard House','บ้านชั้นเดียวคอร์ตยาร์ดสไตล์แจแปนดิ','Zen & Scandi Harmony','japandi',1,185,'[185]',3,2,2,15,20,75,2.8,3.4,24900,32000,'COURTYARD MINIMAL','บ้านชั้นเดียวโอบล้อมสวนหินเซน ระแนงไม้บานเลื่อน เหมาะกับผู้สูงอายุ','บ้านชั้นเดียวผังรูปตัว U โอบล้อมคอร์ตยาร์ดกลางบ้าน ทุกห้องรับแสงธรรมชาติและลมถ่ายเท พื้นระดับเดียวทั้งหลัง ไม่มีธรณีประตู รองรับ Universal Design สำหรับผู้สูงอายุ','/images/japandi-courtyard.jpg','{/images/japandi-courtyard.jpg,/images/built-selaphum-courtyard.jpg,/images/interior-360.jpg}','{universal,tour360}',30,18,14,30),
('AP-SECTION-3D','Open Concept Villa','บ้านสองชั้นโถงสูง Open Concept','Interactive Section View','modern',2,290,'[160,130]',3,4,2,15,20,75,4.2,4.9,29500,39000,'SECTION VIEW','ผังเปิดโล่ง โถงบันไดสูงสองชั้น ดูโครงสร้างได้ผ่านโมเดลตัด 3D','บ้านโมเดิร์นสองชั้นผังเปิด เชื่อมห้องนั่งเล่น ห้องอาหาร และครัวเป็นพื้นที่เดียว โถงบันไดสูงโปร่ง ดูการจัดวางทุกห้องผ่านโมเดลตัดแบบ Dollhouse ได้ทันที','/images/section-cutaway.jpg','{/images/section-cutaway.jpg,/images/interior-360.jpg}','{dollhouse,tour360}',36,22,16,40),
('AP-MODERN-04','Modern Contemporary Premium','บ้านโมเดิร์นคอนเทมโพรารี่สองชั้น','Premium BIM Collection','modern',2,385,'[195,190]',4,5,2,18,22,99,5.4,6.2,34900,46000,'PREMIUM BIM','บ้านสองชั้นงานสีเท็กซ์เจอร์ ไฟส่องสว่าง Twilight สวนทรอปิคอลรอบบ้าน','สถาปัตยกรรมโมเดิร์นคอนเทมโพรารี่สองชั้น ผนังไม้สังเคราะห์ตัดสีขาว ระเบียงยื่นรับวิว ชั้นล่างมีห้องนอนผู้สูงอายุ ที่จอดรถในร่ม 2 คัน แบบนี้สร้างจริงแล้วใน อ.เมือง จ.ร้อยเอ็ด (AP-RE-089)','/images/built-roiet-modern.jpg','{/images/built-roiet-modern.jpg,/images/interior-360.jpg,/images/section-cutaway.jpg}','{tour360,dollhouse}',38,24,18,5),
('AP-NRD-295','Nordic Gable Villa 01','วิลล่านอร์ดิกหน้าจั่ว','Modern Scandinavian','nordic',2,295,'[170,125]',4,4,2,16,20,80,4.0,4.6,28500,38000,'3D READY','หลังคาจั่วองศาชันไร้ชายคา หน้าต่างกระจก Double Volume รับแสงทิศเหนือ','หลังคาจั่วองศาชันไร้ชายคา หน้าต่างกระจก Double Volume รับแสงธรรมชาติ ระเบียงทิศเหนือ หลังคา Seam Zinc ไร้รอยต่อป้องกันรั่วซึมจากพายุฝนอีสาน','/images/nordic-single.jpg','{/images/nordic-single.jpg,/images/interior-360.jpg}','{tour360}',36,22,16,50),
('AP-JPN-220','Japandi Courtyard One','บ้านชั้นเดียวคอร์ทกลางบ้าน','Zen Minimalist','japandi',1,220,'[220]',3,3,2,16,22,88,3.0,3.6,24900,31000,'3D READY','บ้านชั้นเดียวโอบล้อมสวนหินเซน ระแนงไม้กันแดดบานเลื่อน','บ้านเดี่ยวชั้นเดียวโอบล้อมสวนหินเซน ระแนงไม้กันแดดบานเลื่อน เหมาะสำหรับครอบครัวที่มีผู้สูงอายุ พื้นที่ส่วนกลางกว้างเชื่อมต่อคอร์ทกลางบ้าน','/images/built-selaphum-courtyard.jpg','{/images/built-selaphum-courtyard.jpg,/images/japandi-courtyard.jpg}','{universal}',32,20,14,60),
('AP-TRP-440','Tropical Oasis Villa X','คฤหาสน์โมเดิร์นทรอปิคอล','Modern Luxury Tropical','tropical',2,440,'[245,195]',5,6,3,22,26,143,7.2,8.4,39500,52000,'POOL LUXURY','คฤหาสน์โมเดิร์นสระว่ายน้ำ 4 x 11 เมตร ห้องนอน 5 ห้อง','คฤหาสน์โมเดิร์นทรอปิคอลสองชั้น สระว่ายน้ำ 4 x 11 เมตร ห้องรับรองแขกแยกส่วน ห้องนอน 5 ห้องพร้อมห้องน้ำในตัว และห้องแม่บ้าน','/images/tropical-villa.jpg','{/images/tropical-villa.jpg,/images/interior-360.jpg}','{pool,tour360}',46,28,22,70),
('AP-MINI-120','Minimal Box 120','บ้านมินิมอลชั้นเดียว งบประหยัด','Minimal 1-Storey','minimal',1,120,'[120]',2,2,1,12,16,48,1.6,1.9,15900,21000,'BUDGET','บ้านชั้นเดียวขนาดกะทัดรัด งบก่อสร้างไม่ถึง 2 ล้าน','บ้านมินิมอลชั้นเดียว 2 ห้องนอน 2 ห้องน้ำ ผังเรียบง่ายก่อสร้างไว ใช้โครงสร้างมาตรฐานลดต้นทุน เหมาะสำหรับครอบครัวเล็กหรือบ้านพักผู้สูงอายุ','/images/japandi-courtyard.jpg','{/images/japandi-courtyard.jpg}','{universal}',24,16,12,80),
('AP-NARROW-09','Narrow Lot Nordic','บ้านสองชั้นสำหรับที่ดินหน้าแคบ','Urban Narrow Lot','nordic',2,165,'[90,75]',3,3,1,8,20,40,2.6,3.1,21900,28000,'NARROW LOT','หน้ากว้างเพียง 8 เมตร ใช้พื้นที่คุ้มค่า เหมาะที่ดินในเมือง','บ้านนอร์ดิกสองชั้นสำหรับที่ดินหน้าแคบ 8 เมตร วางผังแนวลึก ช่องแสงหลังคาช่วยให้ภายในสว่าง โครงสร้างเหมาะกับที่ดินในเขตเทศบาล','/images/nordic-single.jpg','{/images/nordic-single.jpg,/images/section-cutaway.jpg}','{narrow}',30,20,14,90);

