insert into public.projects (code,title,style_label,district,plan_code,area_sqm,bedrooms,bathrooms,budget_million,highlight,description,quote,quote_by,handover_on,image,before_image,featured,sort_order) values
('AP-RE-089','บ้านโมเดิร์นคอนเทมโพรารี่ 2 ชั้น','Modern Contemporary','อ.เมืองร้อยเอ็ด','AP-MODERN-04',320,4,5,4.75,'ส่งมอบก่อนกำหนด 16 วัน','สถาปัตยกรรมโมเดิร์นคอนเทมโพรารี่ 2 ชั้น งานสีเท็กซ์เจอร์เกรดพรีเมียม สวนทรอปิคอลรอบบ้าน ระบบไฟส่องสว่างค่ำคืน Twilight และตรวจ Thermal Scan ผ่านทุกจุด','สร้างบ้านกับ ArchiPlan สบายใจมากที่สุดครับ วิศวกรตรวจคุมงานละเอียดทุกงวด บ้านตรงปกเหมือนโมเดล 3D ที่เราหมุนดูในระบบ BIM ทุกกระเบียดนิ้ว ที่สำคัญคือคุมงบได้ตาม BOQ เป๊ะ','คุณปิยะพงษ์ & คุณณัชชา บุญทวี','2023-12-20','/images/built-roiet-modern.jpg','/images/construction-before.jpg',true,1),
('RE-SL-034','บ้านเดี่ยวชั้นเดียว คอร์ตยาร์ดกลางบ้าน','Japandi Courtyard','อ.เสลภูมิ','AP-JPN-220',185,3,2,2.85,'ผ่านตรวจ 0 Defect','ดีไซน์เน้นพื้นที่สวนหินเซนและคอร์ทกลางบ้านเพื่อรับแสงธรรมชาติ ผนังสีขาวเท็กซ์เจอร์ผสมระแนงไม้ธรรมชาติอบอุ่น','ชอบคอร์ทยาร์ดต้นไม้กลางบ้านมากค่ะ ลมถ่ายเทดีแม้ในหน้าร้อน ไม่ต้องเปิดแอร์ทั้งวัน ช่างเก็บงานเรียบร้อยมาก','คุณพรรณิภา (อาจารย์ มรภ.ร้อยเอ็ด)','2024-02-15','/images/built-selaphum-courtyard.jpg',null,false,2),
('RE-PT-072','วิลล่า 2 ชั้น นอร์ดิกหน้าจั่วทรงสูง','Nordic Gable Villa','อ.โพนทอง','AP-NRD-295',295,4,4,4.20,'วิศวกรโครงสร้างตรวจ 6 งวด','ดีไซน์หลังคา Seam Zinc ไร้รอยต่อ ป้องกันปัญหารั่วซึมจากฝนฟ้าคะนองในภาคอีสาน หน้าต่างกระจก Insulated Glass กระจกหนา 2 ชั้น','ตอนแรกกังวลเรื่องหลังคาจั่วสูงว่าจะมีปัญหาน้ำรั่วไหม ทีมงานใช้ระบบ Seam ไร้รอยต่อ ฝนตกหนักพายุเข้าไม่มีหยดเลย ประทับใจมาก','คุณหมอเอกชัย (แพทย์ รพ.โพนทอง)','2024-03-10','/images/nordic-single.jpg',null,false,3),
('RE-TB-018','บ้านพักอาศัยโมเดิร์นทรอปิคอล ชั้นเดียว','Modern Zen Living','อ.ธวัชบุรี','AP-JAPANDI-01',210,3,3,3.15,'คุมงานตามงบ BOQ เป๊ะ','บ้านชั้นเดียวที่เน้นความสงบ เป็นส่วนตัว ผสมผสานวัสดุไม้ระแนงสังเคราะห์กันแดดบ่าย พร้อมทางเดินเชื่อมต่อสู่สวนหินญี่ปุ่น','สร้างบ้านให้คุณแม่พักผ่อนในวัยเกษียณ ทางลาดและระดับพื้นในบ้านไม่มีสะดุด วัสดุตรงตามที่ระบุในสัญญาทุกอย่าง ขอบคุณทีมวิศวกรครับ','คุณธีรเดช (เจ้าของธุรกิจส่วนตัว)','2024-01-18','/images/japandi-courtyard.jpg',null,false,4),
('RE-KV-051','บ้านทรอปิคอลวิลล่าพร้อมสระว่ายน้ำ','Tropical Villa','อ.เกษตรวิสัย','AP-TROPICAL-02',385,4,5,6.60,'รายงานความคืบหน้าวิดีโอ 360° ทุกสัปดาห์','บ้านสองชั้นสไตล์รีสอร์ตพร้อมสระว่ายน้ำระบบเกลือ เจ้าของบ้านอยู่กรุงเทพฯ ติดตามงานผ่านรายงาน 360° และ LINE ทุกสัปดาห์','เราอยู่กรุงเทพฯ แต่สร้างบ้านให้พ่อแม่อยู่ที่เกษตรวิสัย มีรายงานความคืบหน้าแบบวิดีโอ 360 องศาให้ดูทุกสัปดาห์ ไม่ต้องเดินทางมาคุมงานเองเลย','คุณรสรินทร์ ชินวงศ์','2024-06-30','/images/tropical-villa.jpg',null,false,5);

insert into public.reviews (name,role,district,rating,body,sort_order) values
('คุณรสรินทร์ ชินวงศ์','เภสัชกร (บ้านชั้นเดียว 160 ตร.ม.)','อ.เกษตรวิสัย',5,'เราอยู่กรุงเทพฯ แต่สร้างบ้านให้พ่อแม่อยู่ที่เกษตรวิสัย ArchiPlan รายงานความคืบหน้าผ่านแอปและ LINE แบบถ่ายวิดีโอ 360 องศาให้ดูทุกสัปดาห์ ไม่ต้องเดินทางมาคุมงานเองเลย สะดวกและมืออาชีพมากค่ะ',1),
('พ.ต.ท. กิตติศักดิ์ มหาชัย','ข้าราชการตำรวจ (บ้าน 2 ชั้น 240 ตร.ม.)','อ.จตุรพักตรพิมาน',5,'ชอบขั้นตอนการเขียนแบบ 3D BIM มาก สถาปนิกช่วยปรับให้เข้ากับทิศทางแดดลมของที่ดินเดิม ทำให้บ้านไม่ร้อน และช่วยประสานงานยื่นขออนุญาตก่อสร้างกับ อบต. ให้แบบเสร็จสรรพไม่มีสะดุด',2),
('คุณชัชวาล เลิศปัญญา','ผู้จัดการสาขาธนาคาร (บ้านเดี่ยวชั้นเดียว)','อ.เสลภูมิ',5,'ตรวจรับบ้าน Defect น้อยมาก แทบจะไม่มีจุดแก้งานใหญ่เลย วันส่งมอบมีวิศวกรนำกล้อง Thermal Scan มาตรวจเช็กการรั่วซึมและความร้อนให้ดูสดๆ ประทับใจในมาตรฐานทางวิศวกรรมมากครับ',3);

